import Foundation
import SwiftUI
#if canImport(AppKit)
import AppKit
#else
import UIKit
#endif

/// **The real logo of each AI provider**, on every Mac and on the iPhone, also where that provider's app is not
/// installed (the owner, 31 October 2026: "proper logos for chrome, claude, chatpgto and any other ai provider we
/// have", and his yes to the page that showed them). Each is the icon of the provider's own Mac app at 128 pixels. The
/// bytes stand here, so the apps still bundle no image file and read no network. The logos are their owners' marks:
/// Founderizer shows them only to name the provider.
public enum ProviderLogo {
    /// The logo of a runtime, or of a provider of an agent on a key (the AI providers build: `gemini`, `opencode` for
    /// OpenCode Go, `openrouter`, `ollama`), nil for a provider that has none here. The owner's own model server has
    /// none: its mark is the server symbol, which the app draws itself.
    public static func image(_ runtime: String) -> Image? {
        switch runtime {
        case "claude": claude
        case "codex": chatGPT
        case "grok": grok
        case "gemini": gemini
        case "opencode": openCode
        case "openrouter": openRouter
        case "ollama": ollama
        default: nil
        }
    }

    private static let claude = decode(claudeBytes)
    private static let chatGPT = decode(chatGPTBytes)
    private static let grok = decode(grokBytes)
    private static let gemini = decode(geminiBytes)
    private static let openCode = decode(openCodeBytes)
    private static let openRouter = decode(openRouterBytes)
    private static let ollama = decode(ollamaBytes)

    private static func decode(_ bytes: String) -> Image? {
        guard let data = Data(base64Encoded: bytes) else { return nil }
        #if canImport(AppKit)
        return NSImage(data: data).map(Image.init(nsImage:))
        #else
        return UIImage(data: data).map(Image.init(uiImage:))
        #endif
    }

    // /Applications/Claude.app, electron.icns
    static let claudeBytes = ""
    // /Applications/ChatGPT.app, icon-chatgpt.icns
    static let chatGPTBytes = ""
    // /Applications/Grok Bot.app, icon.icns
    static let grokBytes = ""

    // **The four providers that have no Mac app** (the AI providers build, 16 November 2026): each one's own mark, read
    // from its own site or its own files, on the tile of the three icons above (a 102-pixel continuous square at 13
    // pixels of 128), in the colours of the provider's own icon. Gemini: Google's four-point star on white. OpenCode
    // (OpenCode Go): its frame on near-black, from opencode.ai. OpenRouter: its mark in its lime on near-black, from
    // openrouter.ai. Ollama: its llama on white.
    static let geminiBytes = ""
    static let openCodeBytes = ""
    static let openRouterBytes = ""
    static let ollamaBytes = ""
}
